import { CONFIG } from './config.js';
import { getSession,signInWithPassword,signOut,invoke,select } from './supabase-client.js';
import { bootstrapContext,onboardCompany,updateModule,loadOperationalData } from './live-data.js';
import { demo } from './demo-data.js';

const $=s=>document.querySelector(s), app=$('#app');
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const yes=v=>v?'<span class="tag on">Yes</span>':'<span class="tag off">No</span>';
const status=v=>`<span class="tag ${['ACTIVE','OPEN','READY','RELEASED','COMPLETED','PRINTED'].includes(String(v).toUpperCase())?'on':['EXCEPTION','FAILED','CANCELLED'].includes(String(v).toUpperCase())?'danger':''}">${esc(v??'—')}</span>`;
const fmtDate=v=>v?new Date(v).toLocaleString():'—';
const state={session:null,ctx:null,admin:null,ops:null,page:'home',demo:CONFIG.DEMO_MODE,facilityId:null,clientId:null,tenantTarget:null};
function toast(msg,err=false){const n=document.createElement('div');n.className='toast'+(err?' err':'');n.textContent=msg;document.body.append(n);setTimeout(()=>n.remove(),3800)}
function loading(text='Loading FlowStock…'){app.innerHTML=`<div class="load"><div><div class="mark" style="margin:auto">F</div><p>${esc(text)}</p></div></div>`}
function table(cols,rows){if(!rows?.length)return '<div class="empty">No records yet.</div>';return `<div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c.html?c.html(r):esc(c.val?r[c.val]:'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function can(screen,cap='view'){if(state.demo)return true;const role=state.admin?.role||state.ctx?.role;if(['OWNER','ADMIN'].includes(role))return true;const p=(state.admin?.allowed_screens||[]).find(x=>x.screen_key===screen);return !!p?.[`can_${cap}`]}
function modules(){return state.ctx?.modules||{}}
function moduleOn(k){return !!modules()[k]}
function activeCompany(){return state.ctx?.company||{}}

async function resolveHostTenant(){
 if(state.demo)return null;
 const hostname=String(location.hostname||'').toLowerCase();
 if(!hostname)return null;
 try{const r=await invoke('tenant-resolve',{hostname});state.tenantTarget=r?.tenant||null;return state.tenantTarget}catch(e){console.warn('Tenant hostname resolution failed',e);return null}
}
async function start(){loading();if(state.demo){state.session={user:{email:'demo@flowstock.local'}};state.ctx={companyId:'demo-company',company:{id:'demo-company',name:demo.context.company,code:'DEMO',is_3pl:true,timezone:'Asia/Kolkata',currency:'INR'},role:'OWNER',facilities:demo.facilities.map((x,i)=>({id:'f'+i,...x})),clients:demo.clients.map((x,i)=>({id:'c'+i,...x})),modules:demo.context.modules};state.facilityId=state.ctx.facilities[0].id;state.clientId=state.ctx.clients[0]?.id||null;state.admin={role:'OWNER',items:demo.items.map((x,i)=>({id:'i'+i,...x,base_uom:x.uom,lot_controlled:x.lot,serial_controlled:x.serial,expiry_controlled:x.expiry,active:true})),locations:demo.locations.map((x,i)=>({id:'l'+i,...x,location_type:x.type,lpn_controlled:x.lpnControlled,lpn_required:x.lpnRequired,active:true})),zones:[],customers:[],suppliers:[],uoms:[{id:'u1',code:'EA',name:'Each',uom_class:'QUANTITY',conversion_rate:1,active:true}],facilities:state.ctx.facilities,clients:state.ctx.clients,groups:[],screen_instances:[],menus:[],audit:[],allowed_screens:[]};state.ops={...demo};renderShell();return;}
 await resolveHostTenant();state.session=await getSession();if(!state.session){renderLogin();return;}await loadContext();}

function renderLogin(){app.innerHTML=`<div class="auth"><section class="loginpane"><form class="loginbox" id="loginForm"><h2>FlowStock WMS</h2><p>${state.tenantTarget?`Sign in to <b>${esc(state.tenantTarget.name)}</b>.`:'Sign in to your warehouse.'}</p><div class="field"><label>Email</label><input name="email" type="email" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn primary" type="submit">Sign in</button><p><a href="./reset-password.html">Forgot password?</a></p><div id="loginErr" class="mini"></div></form></section></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{loading('Signing in…');await signInWithPassword(f.get('email'),f.get('password'));state.session=await getSession();await loadContext()}catch(err){renderLogin();$('#loginErr').textContent=err.message;$('#loginErr').style.color='#a22'}}}

async function loadContext(){loading('Loading tenant context…');const targetId=state.tenantTarget?.company_id||null;let b;try{b=await bootstrapContext(targetId)}catch(e){if(String(e.message).includes('TENANT_ACCESS_DENIED')){renderTenantDenied();return}throw e}if(!b.memberships?.length){if(state.tenantTarget){renderTenantDenied();return}renderOnboarding();return;}const m=(targetId?b.memberships.find(x=>x.company_id===targetId):null)||b.memberships.find(x=>x.company_id===b.selected_company_id)||b.memberships[0],company=m.wms_companies;state.ctx={companyId:m.company_id,company,role:m.role,facilities:b.facilities||[],clients:b.clients||[],modules:Object.fromEntries((b.modules||[]).map(x=>[x.module_key,!!x.enabled]))};state.facilityId=localStorage.getItem('flowstock.facility')||state.ctx.facilities[0]?.id||null;state.clientId=company.is_3pl?(localStorage.getItem('flowstock.client')||state.ctx.clients[0]?.id||null):null;await refreshData();renderShell();}

function renderTenantDenied(){app.innerHTML=`<div class="onboard"><div class="card"><div class="brand" style="color:var(--ink);padding:0 0 18px"><div class="mark">F</div><div>FlowStock<small>Tenant access</small></div></div><h1>Access not assigned</h1><div class="notice warn">Your signed-in account is not assigned to ${esc(state.tenantTarget?.name||'this FlowStock tenant')}.</div><p class="mini">Ask the tenant administrator to add this user, or sign in with an account that belongs to this tenant URL.</p><button class="btn" id="tenantDeniedLogout">Sign out</button></div></div>`;$('#tenantDeniedLogout').onclick=async()=>{await signOut();location.reload()}}

function renderOnboarding(){app.innerHTML=`<div class="onboard"><form class="card" id="onboardForm"><div class="brand" style="color:var(--ink);padding:0 0 18px"><div class="mark">F</div><div>FlowStock<small>First workspace</small></div></div><h1>Create your workspace</h1><p class="mini">Company/facility names, timezone and currency can be changed later. Company/facility codes and the 3PL operating model should be treated as controlled once operations begin.</p><div class="notice warn" style="margin:14px 0">3PL determines whether inventory can be owned by multiple clients. Choose this based on your operating model, not only today's first warehouse.</div><div class="form"><div class="field"><label>Company code</label><input name="code" required placeholder="VNL"></div><div class="field"><label>Company name</label><input name="name" required placeholder="Vinaysa Logistics"></div><div class="field"><label>3PL operation?</label><select name="is_3pl"><option value="false">No</option><option value="true">Yes</option></select></div><div class="field"><label>Timezone</label><input name="timezone" value="Asia/Kolkata"></div><div class="field"><label>Currency</label><input name="currency" value="INR"></div><div class="field"><label>First facility code</label><input name="facility_code" value="MAIN" required></div><div class="field full"><label>First facility name</label><input name="facility_name" value="Main Warehouse" required></div></div><div style="display:flex;justify-content:flex-end;margin-top:16px"><button class="btn primary">Create workspace</button></div></form></div>`;$('#onboardForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));o.is_3pl=o.is_3pl==='true';try{loading('Creating workspace…');await onboardCompany(o);await loadContext()}catch(err){renderOnboarding();toast(err.message,true)}}}

async function refreshData(){if(state.demo)return;const companyId=state.ctx.companyId;const admin=await invoke('admin-bootstrap',{company_id:companyId});state.admin=admin;state.ops=state.facilityId?await loadOperationalData({companyId,facilityId:state.facilityId,clientId:state.clientId,modules:state.ctx.modules}):{};}

const navDefs=[
 ['Workspace',[['home','HOME','Overview'],['modules','ADMIN_TENANT','Modules']]],
 ['Master Data',[['items','MASTER_ITEMS','Items'],['locations','MASTER_LOCATIONS','Locations'],['customers','MASTER_CUSTOMERS','Customers'],['suppliers','MASTER_SUPPLIERS','Suppliers'],['uom','MASTER_UOM','UOM']]],
 ['Operations',[['inventory','INVENTORY_INQUIRY','Inventory'],['receiving','INBOUND_RECEIVING','Receiving'],['transactions','INVENTORY_TRANSACTIONS','Transactions'],['orders','OMS_ORDERS','Orders'],['waves','WMS_WAVES','Waves'],['tasks','WMS_TASKS','Tasks'],['rules','WMS_RULES','Rule Studio'],['shipping','SHIPPING','Shipping'],['history','TRANSACTION_HISTORY','Transaction History'],['printing','PRINTING','Print Center'],['rf','RF_INQUIRY','RF / Mobile']]],
 ['Administration',[['facilities','ADMIN_FACILITIES','Facilities & 3PL'],['users','ADMIN_USERS','Users'],['security','ADMIN_SECURITY','Groups / Screens'],['tenant','ADMIN_TENANT','Tenant & Domains']]]
];
const screenModule={MASTER_CUSTOMERS:'OMS',OMS_ORDERS:'OMS',WMS_WAVES:'WMS',WMS_TASKS:'WMS',WMS_RULES:'WMS',SHIPPING:'SHIPPING'};
function visibleNav(){return navDefs.map(([s,items])=>[s,items.filter(([p,screen])=>can(screen,'view')&&(!screenModule[screen]||moduleOn(screenModule[screen]))) ]).filter(x=>x[1].length)}
function renderShell(){const nav=visibleNav().map(([sec,items])=>`<div class="navsec">${esc(sec)}</div>${items.map(([p,,label])=>`<button data-page="${p}" class="${state.page===p?'active':''}"><i class="dot"></i><span>${esc(label)}</span></button>`).join('')}`).join('');app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="mark">F</div><div class="txt">FlowStock<small>Operations Platform</small></div></div><nav class="nav">${nav}</nav><div class="sidefoot">v3.0 · ${esc(state.admin?.role||state.ctx.role)}<br>${esc(activeCompany().name||'Tenant')}</div></aside><main class="main"><header class="topbar"><div class="context"><select id="facilitySel">${(state.ctx.facilities||[]).map(f=>`<option value="${f.id}" ${f.id===state.facilityId?'selected':''}>${esc(f.code)} · ${esc(f.name)}</option>`).join('')}</select>${activeCompany().is_3pl?`<select id="clientSel"><option value="">All / none</option>${(state.ctx.clients||[]).map(c=>`<option value="${c.id}" ${c.id===state.clientId?'selected':''}>${esc(c.code)} · ${esc(c.name)}</option>`).join('')}</select>`:''}</div><div class="spacer"></div>${Object.entries(modules()).filter(x=>x[1]).map(([k])=>`<span class="pill">${esc(k)}</span>`).join('')}<span class="user">${esc(state.session?.user?.email||'Demo')}</span><button class="btn" id="logoutBtn">Sign out</button></header><section class="content" id="page"></section></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;renderShell()});$('#facilitySel')?.addEventListener('change',async e=>{state.facilityId=e.target.value;localStorage.setItem('flowstock.facility',state.facilityId);await reloadAndRender()});$('#clientSel')?.addEventListener('change',async e=>{state.clientId=e.target.value||null;if(state.clientId)localStorage.setItem('flowstock.client',state.clientId);else localStorage.removeItem('flowstock.client');await reloadAndRender()});$('#logoutBtn').onclick=async()=>{if(!state.demo)await signOut();location.reload()};renderPage().catch(e=>{toast(e.message,true);$('#page').innerHTML=`<div class="notice warn">${esc(e.message)}</div>`})}
async function reloadAndRender(){loading('Refreshing warehouse context…');await refreshData();renderShell()}

function head(title,desc,actions=''){return `<div class="pagehead"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="actions">${actions}</div></div>`}
function actionButton(id,label,primary=true,disabled=false){return `<button class="btn ${primary?'primary':''}" id="${id}" ${disabled?'disabled':''}>${esc(label)}</button>`}
function idName(list,id,code='code'){const x=(list||[]).find(z=>z.id===id);return x?.[code]||x?.name||'—'}
function pageEl(){return $('#page')}
async function renderPage(){switch(state.page){case'home':return pageHome();case'modules':return pageModules();case'items':return pageItems();case'locations':return pageLocations();case'customers':return pageCustomers();case'suppliers':return pageSuppliers();case'uom':return pageUom();case'facilities':return pageFacilities();case'users':return pageUsers();case'security':return pageSecurity();case'tenant':return pageTenant();case'inventory':return pageInventory();case'receiving':return pageReceiving();case'transactions':return pageTransactions();case'history':return pageHistory();case'orders':return pageOrders();case'waves':return pageWaves();case'tasks':return pageTasks();case'rules':return pageRules();case'shipping':return pageShipping();case'printing':return pagePrinting();case'rf':return pageRf();default:state.page='home';return pageHome()}}

function pageHome(){const o=state.ops||{},inv=o.inventory||[],tasks=o.tasks||[],orders=o.orders||[];pageEl().innerHTML=head('Warehouse overview','One operational surface from inventory through execution.')+`<div class="grid kpis"><div class="kpi"><span>On-hand units</span><strong>${inv.reduce((s,x)=>s+Number(x.qty||0),0)}</strong></div><div class="kpi"><span>Allocated</span><strong>${inv.reduce((s,x)=>s+Number(x.allocated||0),0)}</strong></div><div class="kpi"><span>Open tasks</span><strong>${tasks.filter(x=>!['COMPLETED','CANCELLED'].includes(x.status)).length}</strong></div><div class="kpi"><span>Open orders</span><strong>${orders.filter(x=>!['SHIPPED','CANCELLED'].includes(x.status)).length}</strong></div></div><div class="grid two" style="margin-top:12px"><div class="card"><h3>Execution model</h3><div class="notice">Inventory Core is the shared ledger. OMS and WMS are independently enabled; WMS adds rule-driven execution, tasks, waves, replenishment, LPN/location controls and RF workflows.</div><div style="margin-top:12px" class="rfcard"><div class="mark">RF</div><div><b>Dedicated scan-first application</b><div class="mini">Camera barcode / QR + rugged keyboard-wedge scanners.</div></div><button class="btn" style="margin-left:auto" id="openRf">Open RF</button></div></div><div class="card"><h3>Recent business events</h3>${(o.events||[]).slice(0,8).map(e=>`<div style="padding:7px 0;border-bottom:1px solid var(--line)"><b style="font-size:10px">${esc(e.event)}</b><div class="mini">${esc(e.ref)} · ${esc(e.detail)} · ${esc(e.time)}</div></div>`).join('')||'<div class="empty">No events</div>'}</div></div>`;$('#openRf').onclick=()=>window.open('./rf/','_blank')}

function pageModules(){const catalog={INVENTORY:'Shared inventory ledger and basic execution',OMS:'Orders, reservations, allocation and channels',WMS:'Advanced warehouse execution and rules',THREE_PL:'Client-owned inventory and 3PL context',SHIPPING:'Packing, carriers, shipping and manifests',AUTOMATION:'Rules, events, reports and enterprise printing'};pageEl().innerHTML=head('Modules','Enable capabilities per tenant. Inventory is the shared foundation.')+`<div class="modulegrid">${Object.entries(catalog).map(([k,d])=>`<label class="module"><div><b>${k}</b><small>${esc(d)}</small></div><input type="checkbox" data-module="${k}" ${moduleOn(k)?'checked':''} ${k==='INVENTORY'||!['OWNER','ADMIN'].includes(state.admin?.role)?'disabled':''}></label>`).join('')}</div>`;document.querySelectorAll('[data-module]').forEach(x=>x.onchange=async()=>{try{await updateModule(state.ctx.companyId,x.dataset.module,x.checked);state.ctx.modules[x.dataset.module]=x.checked;toast(`${x.dataset.module} ${x.checked?'enabled':'disabled'}`);renderShell()}catch(e){x.checked=!x.checked;toast(e.message,true)}})}

function masterButtons(screen){return actionButton('addMaster','+ Add',true,!can(screen,'create'))}
function pageItems(){const rows=state.admin.items||[];pageEl().innerHTML=head('Item Master','Item identity, UOM and warehouse control attributes.',masterButtons('MASTER_ITEMS'))+table([{label:'SKU',val:'sku'},{label:'Description',val:'description'},{label:'UOM',val:'base_uom'},{label:'Category',val:'category'},{label:'Lot',html:r=>yes(r.lot_controlled)},{label:'Serial',html:r=>yes(r.serial_controlled)},{label:'Expiry',html:r=>yes(r.expiry_controlled)},{label:'Status',html:r=>status(r.active?'ACTIVE':'INACTIVE')},{label:'',html:r=>`<div class="rowactions"><button class="btn" data-edit="${r.id}">Edit</button><button class="btn" data-toggle="${r.id}">${r.active?'Deactivate':'Activate'}</button></div>`}],rows);$('#addMaster').onclick=()=>itemForm();wireMasterRows(rows,'ITEM',itemForm,'MASTER_ITEMS')}
function itemForm(r={}){openForm(r.id?'Edit item':'Add item',[['sku','Item code','text',r.sku||'',true],['description','Description','text',r.description||'',true],['base_uom','Primary UOM','select',r.base_uom||'EA',true,(state.admin.uoms||[]).filter(x=>x.active).map(x=>[x.code,`${x.code} · ${x.name}`])],['category','Category','text',r.category||''],['client_id','3PL client','select',r.client_id||'',false,[['','Company owned'],...(state.admin.clients||[]).map(x=>[x.id,`${x.code} · ${x.name}`])]],['lot_controlled','Lot controlled','checkbox',!!r.lot_controlled],['serial_controlled','Serial controlled','checkbox',!!r.serial_controlled],['expiry_controlled','Expiry controlled','checkbox',!!r.expiry_controlled],['catch_weight','Catch weight','checkbox',!!r.catch_weight],['weight','Unit weight','number',r.weight??''],['volume','Unit volume','number',r.volume??'']],async d=>saveMaster('ITEM',r.id,d))}

function pageLocations(){const zones=state.admin.zones||[],rows=(state.admin.locations||[]).filter(x=>!state.facilityId||x.facility_id===state.facilityId);pageEl().innerHTML=head('Location Master','Zones, storage behavior, LPN controls, picking and replenishment.',`${actionButton('addZone','+ Zone',false,!can('MASTER_LOCATIONS','create'))}${actionButton('addMaster','+ Location',true,!can('MASTER_LOCATIONS','create'))}`)+table([{label:'Location',val:'code'},{label:'Zone',html:r=>esc(idName(zones,r.zone_id))},{label:'Type',val:'location_type'},{label:'LPN allowed',html:r=>yes(r.lpn_controlled)},{label:'LPN required',html:r=>yes(r.lpn_required)},{label:'Pickable',html:r=>yes(r.pickable)},{label:'Blocked',html:r=>yes(r.blocked)},{label:'Status',html:r=>status(r.active?'ACTIVE':'INACTIVE')},{label:'',html:r=>`<div class="rowactions"><button class="btn" data-edit="${r.id}">Edit</button><button class="btn" data-toggle="${r.id}">${r.active?'Deactivate':'Activate'}</button></div>`}],rows);$('#addMaster').onclick=()=>locationForm();$('#addZone').onclick=()=>zoneForm();wireMasterRows(rows,'LOCATION',locationForm,'MASTER_LOCATIONS')}
function locationForm(r={}){const zs=(state.admin.zones||[]).filter(z=>!state.facilityId||z.facility_id===state.facilityId);openForm(r.id?'Edit location':'Add location',[['code','Location code','text',r.code||'',true],['facility_id','Facility','select',r.facility_id||state.facilityId,true,(state.admin.facilities||[]).map(x=>[x.id,`${x.code} · ${x.name}`])],['zone_id','Zone','select',r.zone_id||'',false,[['','No zone'],...zs.map(x=>[x.id,`${x.code} · ${x.name}`])]],['location_type','Location type','select',r.location_type||'STORAGE',true,['STORAGE','RECEIVING','STAGING','PICK','RESERVE','PACK','SHIPPING','DOCK'].map(x=>[x,x])],['lpn_controlled','LPN allowed','checkbox',!!r.lpn_controlled],['lpn_required','LPN required','checkbox',!!r.lpn_required],['allocatable','Allocatable','checkbox',r.allocatable!==false],['pickable','Pickable','checkbox',r.pickable!==false],['replenishable','Replenishable','checkbox',r.replenishable!==false],['blocked','Blocked','checkbox',!!r.blocked],['max_units','Max units','number',r.max_units??''],['sequence_no','Sequence','number',r.sequence_no??100]],async d=>{if(d.lpn_required)d.lpn_controlled=true;return saveMaster('LOCATION',r.id,d)})}
function zoneForm(r={}){openForm(r.id?'Edit zone':'Add zone',[['code','Zone code','text',r.code||'',true],['name','Name','text',r.name||'',true],['facility_id','Facility','select',r.facility_id||state.facilityId,true,(state.admin.facilities||[]).map(x=>[x.id,`${x.code} · ${x.name}`])],['zone_type','Zone type','select',r.zone_type||'STORAGE',true,['STORAGE','PICK','RESERVE','INBOUND','OUTBOUND','COLD','HAZMAT'].map(x=>[x,x])]],async d=>saveMaster('ZONE',r.id,d))}

function pageCustomers(){const rows=state.admin.customers||[];pageEl().innerHTML=head('Customer Master','Ship-to and customer references used by OMS and shipping.',masterButtons('MASTER_CUSTOMERS'))+table([{label:'Code',val:'customer_code'},{label:'Name',val:'name'},{label:'Email',val:'email'},{label:'Phone',val:'phone'},{label:'Client',html:r=>esc(idName(state.admin.clients,r.client_id))},{label:'Status',html:r=>status(r.active?'ACTIVE':'INACTIVE')},{label:'',html:r=>`<button class="btn" data-edit="${r.id}">Edit</button>`}],rows);$('#addMaster').onclick=()=>customerForm();wireMasterRows(rows,'CUSTOMER',customerForm,'MASTER_CUSTOMERS')}
function customerForm(r={}){openForm(r.id?'Edit customer':'Add customer',[['customer_code','Customer code','text',r.customer_code||'',true],['name','Name','text',r.name||'',true],['email','Email','email',r.email||''],['phone','Phone','text',r.phone||''],['client_id','3PL client','select',r.client_id||'',false,[['','Company owned'],...(state.admin.clients||[]).map(x=>[x.id,`${x.code} · ${x.name}`])]],['ship_to','Ship-to JSON','textarea',JSON.stringify(r.ship_to||{},null,2)]],async d=>{d.ship_to=parseJson(d.ship_to);return saveMaster('CUSTOMER',r.id,d)})}
function pageSuppliers(){const rows=state.admin.suppliers||[];pageEl().innerHTML=head('Supplier Master','Supplier references for PO/ASN/receiving operations.',masterButtons('MASTER_SUPPLIERS'))+table([{label:'Code',val:'supplier_code'},{label:'Name',val:'name'},{label:'Email',val:'email'},{label:'Phone',val:'phone'},{label:'Client',html:r=>esc(idName(state.admin.clients,r.client_id))},{label:'Status',html:r=>status(r.active?'ACTIVE':'INACTIVE')},{label:'',html:r=>`<button class="btn" data-edit="${r.id}">Edit</button>`}],rows);$('#addMaster').onclick=()=>supplierForm();wireMasterRows(rows,'SUPPLIER',supplierForm,'MASTER_SUPPLIERS')}
function supplierForm(r={}){openForm(r.id?'Edit supplier':'Add supplier',[['supplier_code','Supplier code','text',r.supplier_code||'',true],['name','Name','text',r.name||'',true],['email','Email','email',r.email||''],['phone','Phone','text',r.phone||''],['client_id','3PL client','select',r.client_id||'',false,[['','Company owned'],...(state.admin.clients||[]).map(x=>[x.id,`${x.code} · ${x.name}`])]],['address','Address JSON','textarea',JSON.stringify(r.address||{},null,2)]],async d=>{d.address=parseJson(d.address);return saveMaster('SUPPLIER',r.id,d)})}
function pageUom(){const rows=state.admin.uoms||[];pageEl().innerHTML=head('Units of Measure','Company UOM definitions and conversion factors.',masterButtons('MASTER_UOM'))+table([{label:'Code',val:'code'},{label:'Name',val:'name'},{label:'Class',val:'uom_class'},{label:'Base UOM',val:'base_uom_code'},{label:'Conversion',val:'conversion_rate'},{label:'Status',html:r=>status(r.active?'ACTIVE':'INACTIVE')},{label:'',html:r=>`<button class="btn" data-edit="${r.id}">Edit</button>`}],rows);$('#addMaster').onclick=()=>uomForm();wireMasterRows(rows,'UOM',uomForm,'MASTER_UOM')}
function uomForm(r={}){openForm(r.id?'Edit UOM':'Add UOM',[['code','Code','text',r.code||'',true],['name','Name','text',r.name||'',true],['uom_class','UOM class','text',r.uom_class||'QUANTITY'],['base_uom_code','Base UOM','text',r.base_uom_code||''],['conversion_rate','Conversion rate','number',r.conversion_rate??1,true]],async d=>saveMaster('UOM',r.id,d))}

