function checks(prefix,arr,selected=[]){return arr.map(x=>`<label class="check"><input type="checkbox" data-check="${prefix}" value="${x.id}" ${selected.includes(x.id)?'checked':''}>${esc(x.code||x.name)} · ${esc(x.name||'')}</label>`).join('')||'<div class="mini">None configured</div>'}
function getChecked(p){return [...document.querySelectorAll(`[data-check="${p}"]:checked`)].map(x=>x.value)}

