function ruleForm(r={}){openForm(r.id?'Edit rule':'Create rule',[['code','Rule code','text',r.code||'',true],['name','Name','text',r.name||'',true],['rule_type','Rule type','select',r.rule_type||'ALLOCATION',true,['ALLOCATION','PUTAWAY','PICKING','REPLENISHMENT','TASK_ASSIGNMENT','CYCLE_COUNT'].map(x=>[x,x])],['context_object','Context object','text',r.context_object||'INVENTORY',true],['status','Status','select',r.status||'DRAFT',true,['DRAFT','ACTIVE','INACTIVE','RETIRED'].map(x=>[x,x])],['priority','Priority','number',r.priority??100,true],['expression','Expression / condition','textarea',r.expression||'',true],['visual_definition','Visual definition JSON','textarea',JSON.stringify(r.visual_definition||{},null,2)],['result_definition','Result JSON','textarea',JSON.stringify(r.result_definition||{},null,2)]],async d=>{d.priority=Number(d.priority);d.visual_definition=parseJson(d.visual_definition);d.result_definition=parseJson(d.result_definition);await saveMaster('RULE',r.id,d)})}
function pageShipping(){pageEl().innerHTML=head('Shipping','Pack containers, shipments, carriers and dispatch status.')+`<div class="grid two"><div>${table([{label:'Shipment',val:'number'},{label:'Status',html:r=>status(r.status)},{label:'Tracking',val:'tracking'},{label:'Manifest',val:'manifest'},{label:'Packages',val:'packages'}],state.ops?.shipments||[])}</div><div>${table([{label:'Carrier',val:'code'},{label:'Name',val:'name'},{label:'Services',val:'services'}],state.ops?.carriers||[])}</div></div>`}
function pagePrinting(){const printers=state.ops?.printers||[],jobs=state.ops?.printJobs||[];pageEl().innerHTML=head('Print Center','Cloud label printing or local Print Agent / Windows / CUPS document printing.',`${actionButton('addAgent','+ Print Agent',false,!can('PRINTING','update'))}${actionButton('addPrinter','+ Printer',true,!can('PRINTING','update'))}${actionButton('testPrint','Queue test',false,!can('PRINTING','execute'))}`)+`<div class="notice">Labels can route through cloud HTTP or raw Zebra/ZPL Print Agent. Documents can route through a warehouse print server/gateway while durable print jobs preserve retries and idempotency.</div><div class="grid two" style="margin-top:12px"><div>${table([{label:'Printer',val:'code'},{label:'Name',val:'name'},{label:'Transport',val:'transport'},{label:'Format',val:'format'},{label:'Queue',val:'queue'}],printers)}</div><div>${table([{label:'Job',val:'id'},{label:'Printer',val:'printer'},{label:'Type',val:'type'},{label:'Status',html:r=>status(r.status)},{label:'Attempts',val:'attempts'}],jobs)}</div></div>`;$('#addAgent').onclick=()=>openForm('Register facility Print Agent',[['code','Agent code','text','',true],['name','Agent name','text','',true]],async d=>{await invoke('print-config',{action:'REGISTER_AGENT',company_id:state.ctx.companyId,facility_id:state.facilityId,...d});closeModal();await reloadAndRender();toast('Print agent registered')});$('#addPrinter').onclick=()=>openForm('Configure printer',[['code','Printer code','text','',true],['name','Printer name','text','',true],['printer_type','Printer type','select','ZPL',true,[['ZPL','Label / ZPL'],['DOCUMENT','Document']]],['transport','Transport','select','PRINT_AGENT',true,[['PRINT_AGENT','Facility Print Agent'],['CLOUD_HTTP','Cloud HTTP print gateway']]],['agent_id','Agent','select','',false,[['','None'],...(state.ops?.printAgents||[]).map(x=>[x.id,`${x.code} · ${x.name}`])]],['device_uri','Device URI / gateway URL','text',''],['document_format','Format','select','ZPL',true,[['ZPL','ZPL'],['PDF','PDF'],['HTML','HTML']]],['cloud_endpoint','Cloud endpoint (HTTPS)','text',''],['credential_secret_name','Edge secret name','text',''],['queue_name','Queue / printer name','text','']],async d=>{await invoke('print-config',{action:'UPSERT_PRINTER',company_id:state.ctx.companyId,facility_id:state.facilityId,client_id:state.clientId,...d});closeModal();await reloadAndRender();toast('Printer saved')});$('#testPrint').onclick=()=>openForm('Queue test print',[['printer_id','Printer','select',printers[0]?.id||'',true,printers.map(x=>[x.id,`${x.code} · ${x.name}`])],['job_type','Job type','select','LABEL',true,[['LABEL','Label'],['DOCUMENT','Document']]],['document_format','Format','select','ZPL',true,[['ZPL','ZPL'],['PDF','PDF'],['HTML','HTML']]],['payload_text','Payload text / ZPL / HTML','textarea','^XA^FO40,40^FDFlowStock Test^FS^XZ'],['source_url','Controlled HTTPS PDF URL','text','']],async d=>{await invoke('print-job',{company_id:state.ctx.companyId,facility_id:state.facilityId,client_id:state.clientId,printer_id:d.printer_id,job_type:d.job_type,document_format:d.document_format,payload_text:d.payload_text||null,source_url:d.source_url||null,copies:1});closeModal();await reloadAndRender();toast('Print job queued')})}
function pageRf(){pageEl().innerHTML=head('RF / Mobile','Dedicated scan-first warehouse execution application.')+`<div class="card rfcard"><div class="mark">RF</div><div><h3 style="margin:0">Open FlowStock RF</h3><div class="mini">Supports camera BarcodeDetector (where available), QR/1D/2D codes, keyboard-wedge rugged scanners and manual entry.</div></div><button class="btn primary" id="openRf2" style="margin-left:auto">Open in new URL</button></div>`;$('#openRf2').onclick=()=>window.open('./rf/','_blank')}

function wireMasterRows(rows,obj,form,screen){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>form(rows.find(x=>x.id===b.dataset.edit)));document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{const r=rows.find(x=>x.id===b.dataset.toggle);try{await invoke('master-data',{company_id:state.ctx.companyId,object:obj,action:r.active?'DEACTIVATE':'ACTIVATE',id:r.id});await reloadAndRender()}catch(e){toast(e.message,true)}})}
async function saveMaster(object,id,data){if(state.demo){toast('Demo mode: write simulated');closeModal();return}for(const k of Object.keys(data)){if(data[k]==='')data[k]=null;if(['weight','volume','max_units','sequence_no','conversion_rate'].includes(k)&&data[k]!==null)data[k]=Number(data[k])}await invoke('master-data',{company_id:state.ctx.companyId,object,action:id?'UPDATE':'CREATE',id,data});closeModal();await reloadAndRender();toast(`${object} saved`)}
function parseJson(s){if(!s)return{};if(typeof s==='object')return s;try{return JSON.parse(s)}catch{throw new Error('Invalid JSON') }}

function openForm(title,fields,onSave,extra){const html=fields.map(f=>fieldHtml(f)).join('');const back=document.createElement('div');back.className='modalback';back.innerHTML=`<form class="modal" id="modalForm"><div class="modalhead"><h2>${esc(title)}</h2><div class="spacer"></div><button type="button" class="btn" data-close>×</button></div><div class="modalbody"><div class="form">${html}</div>${extra?extra():''}</div><div class="modalfoot"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save</button></div></form>`;document.body.append(back);back.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>back.remove());back.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),d={};for(const f of fields){const [name,,type]=f;if(type==='checkbox')d[name]=e.currentTarget.elements[name].checked;else d[name]=fd.get(name)}try{await onSave(d)}catch(err){toast(err.message,true)}}}
function fieldHtml(f){const [name,label,type='text',value='',required=false,options=[]]=f;const req=required?'required':'';if(type==='checkbox')return `<label class="check"><input name="${name}" type="checkbox" ${value?'checked':''}> ${esc(label)}</label>`;if(type==='select')return `<div class="field"><label>${esc(label)}</label><select name="${name}" ${req}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`;if(type==='textarea')return `<div class="field full"><label>${esc(label)}</label><textarea name="${name}" ${req}>${esc(value)}</textarea></div>`;return `<div class="field"><label>${esc(label)}</label><input name="${name}" type="${type}" value="${esc(value)}" ${req}></div>`}
function closeModal(){document.querySelector('.modalback')?.remove()}

start().catch(e=>{console.error(e);app.innerHTML=`<div class="load"><div><h2>FlowStock could not start</h2><div class="notice warn">${esc(e.message)}</div><button class="btn" onclick="location.reload()" style="margin-top:12px">Retry</button></div></div>`});
